import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import AjvModule from "ajv";
import addFormatsModule from "ajv-formats";
import standaloneCode from "ajv/dist/standalone/index.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(__dirname, "..");
const goldenPath = join(repoRoot, "test/fixtures/physio-mcp-tools.golden.json");
const outPath = join(repoRoot, "src/services/mcp/generated/input-validators.js");

const banner = `/* eslint-disable */
/* Generated by scripts/generate-mcp-input-validators.mjs - do not edit by hand. */
`;

const UCS2LENGTH_HELPER = `
function ucs2length(str) {
  const len = str.length;
  let length = 0;
  for (let i = 0; i < len; ++i) {
    const char = str.charCodeAt(i);
    if (char >= 0xd800 && char <= 0xdbff && i + 1 < len) {
      const next = str.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        length += 2;
        ++i;
        continue;
      }
    }
    length += 1;
  }
  return length;
}
`;

const DATE_FORMAT_HELPER = `
const ajvGeneratedDateFormat = /^\\d\\d\\d\\d-[0-9]\\d-[0-9]\\d$/;
function ajvGeneratedValidateDate(value) {
  return typeof value === "string" && ajvGeneratedDateFormat.test(value);
}
`;

function postProcessStandaloneSource(source) {
  let out = source;
  out = out.replace(
    /const func0 = require\("ajv\/dist\/runtime\/ucs2length"\)\.default;/g,
    "const func0 = ucs2length;",
  );
  out = out.replace(
    /const formats0 = require\("ajv-formats\/dist\/formats"\)\.fullFormats\.date;/g,
    "const formats0 = { validate: ajvGeneratedValidateDate };",
  );
  if (out.includes("require(")) {
    throw new Error(
      "Generated validators still contain require(); adjust postProcessStandaloneSource.",
    );
  }
  return `${UCS2LENGTH_HELPER}${DATE_FORMAT_HELPER}${out}`;
}

function buildGeneratedSource() {
  const golden = JSON.parse(readFileSync(goldenPath, "utf8"));

  const Ajv = AjvModule.default ?? AjvModule;
  const addFormats = addFormatsModule.default ?? addFormatsModule;
  const ajv = new Ajv({
    allErrors: true,
    strict: false,
    validateFormats: true,
    validateSchema: false,
    code: { source: true, esm: true },
  });
  addFormats(ajv);

  const refs = {};
  for (const tool of golden) {
    const id = `physio-mcp-input/${tool.name}`;
    ajv.addSchema({ ...tool.inputSchema, $id: id });
    refs[tool.name] = id;
    ajv.compile({ $ref: id });
  }

  return `${banner}${postProcessStandaloneSource(standaloneCode(ajv, refs))}`;
}

const checkMode = process.argv.includes("--check");
const generated = buildGeneratedSource();

if (checkMode) {
  const committed = readFileSync(outPath, "utf8");
  if (committed !== generated) {
    console.error(
      "Generated MCP input validators are out of date. Run: node scripts/generate-mcp-input-validators.mjs",
    );
    process.exit(1);
  }
  process.exit(0);
}

writeFileSync(outPath, generated, "utf8");
